create table sys_i18n (id varchar(64) not null, create_time datetime(6), create_user varchar(64), event_comment varchar(512), event_name varchar(128), event_time datetime(6), event_user varchar(64), tenant_id varchar(64), trx_id varchar(64), deleted bit not null, description varchar(512), version bigint, code varchar(200) not null, content varchar(2000), locale_code varchar(32) not null, module varchar(64), scope enum ('SYSTEM','USER') not null, primary key (id)) engine=InnoDB;
create table sys_locale (id varchar(64) not null, create_time datetime(6), create_user varchar(64), event_comment varchar(512), event_name varchar(128), event_time datetime(6), event_user varchar(64), tenant_id varchar(64), trx_id varchar(64), deleted bit not null, description varchar(512), version bigint, code varchar(32) not null, is_default bit not null, name varchar(64), sort_no integer, status enum ('DISABLED','ENABLED') not null, primary key (id)) engine=InnoDB;
create index idx_sys_i18n_code on sys_i18n (code);
alter table sys_i18n add constraint uk_sys_i18n_locale_code_tenant unique (locale_code, code, tenant_id, deleted);
alter table sys_locale add constraint uk_sys_locale_code_tenant unique (code, tenant_id, deleted);
